import { ref } from 'vue'

/**
 * A document opens by downloading, never in a panel (the console's useDocumentDownload.ts). The browser's own download
 * bar can sit out of sight, so what was pressed says what happened: each document's state (busy, done, failed) is
 * shared, read by DownloadMark and DownloadButton, and clears 1.8s after. The app hands over the bytes: `get` returns
 * a Blob or text (fetch it from your own API); nothing here calls one.
 */
export type DownloadState = 'busy' | 'done' | 'failed'
const states = ref<Record<string, DownloadState>>({})

/** Every document's download state, by id. */
export const useDownloadState = () => states

function mark(id: string, next?: DownloadState) {
  const all = { ...states.value }
  if (next) all[id] = next
  else delete all[id]
  states.value = all
}

/** download(id, get, name?) saves what `get` returns as `name` (the id, as text, by default). */
export function useDocumentDownload() {
  return async function download(id: string, get: () => Promise<Blob | string> | Blob | string, name?: string) {
    if (states.value[id] === 'busy') return
    mark(id, 'busy')
    try {
      const body = await get()
      const blob = typeof body === 'string' ? new Blob([body], { type: 'text/plain' }) : body
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = name ?? `${id}.txt`
      a.click()
      URL.revokeObjectURL(url)
      mark(id, 'done')
    }
    catch {
      mark(id, 'failed')
    }
    // ds-latency: the check stays a moment after the download, which has already happened.
    setTimeout(() => mark(id), 1800)
  }
}

'use client'
import { Check, Download, X } from 'lucide-react'
import { DotMatrix } from '@/react/components/ui/DotMatrix'
import { useDownloadState, type DownloadState } from '@/react/hooks/useDocumentDownload'

// A document's download at the end of its row (the console's namespaces/DownloadMark.vue, .v2-docdl): a 14px mark,
// muted at rest and ink under the pointer, with a 30px target. Pressed, it says what happened: the dot matrix while
// it works (only after 150ms, so a quick file shows no flash of it), then a check, or a red cross if it failed. The
// marks cross-fade and settle from 0.8 scale. `state` overrides the shared state from useDocumentDownload().
export interface DownloadMarkProps {
  id: string
  state?: DownloadState
  onPress?: () => void
}

export function DownloadMark({ id, state, onPress }: DownloadMarkProps) {
  const shared = useDownloadState()
  const now = state ?? shared[id]
  return (
    <>
      <style href="ds-download-mark" precedence="ds">{css}</style>
      <button data-ds="download-mark" type="button" className="ds-docdl" data-state={now} aria-label={`download ${id}`} onClick={(e) => { e.stopPropagation(); onPress?.() }}>
        <Download data-for="idle" size={14} strokeWidth={1.5} />
        <span data-for="busy" className="inline-grid place-items-center"><DotMatrix /></span>
        <Check data-for="done" size={14} strokeWidth={2} />
        <X data-for="failed" size={14} strokeWidth={2} />
      </button>
      <span data-ds="download-mark" className="sr-only" aria-live="polite">{now === 'done' ? `${id} downloaded` : now === 'failed' ? `${id} failed to download` : ''}</span>
    </>
  )
}

export default DownloadMark

const css = `
.ds-docdl { position: relative; display: inline-grid; width: 14px; height: 14px; flex-shrink: 0; place-items: center; vertical-align: middle; color: var(--ds-color-fg-muted); cursor: pointer; transition: color var(--ds-duration-micro) var(--ds-easing-standard), transform var(--ds-duration-glide) var(--ds-easing-out); }
.ds-docdl::after { position: absolute; inset: -8px; content: ""; }
@media (hover: hover) and (pointer: fine) { .ds-docdl:hover { color: var(--ds-color-fg); } }
.ds-docdl:active { transform: scale(0.92); }
.ds-docdl:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: 4px; }
.ds-docdl > * { grid-area: 1 / 1; opacity: 0; scale: 0.8; transition: opacity var(--ds-duration-micro) var(--ds-easing-standard), scale var(--ds-duration-glide) var(--ds-easing-out); }
.ds-docdl:not([data-state]) > [data-for="idle"], .ds-docdl[data-state="done"] > [data-for="done"], .ds-docdl[data-state="failed"] > [data-for="failed"] { opacity: 1; scale: 1; }
.ds-docdl[data-state="busy"] > [data-for="busy"] { opacity: 1; scale: 1; transition-delay: 150ms; }
.ds-docdl[data-state="done"] { color: var(--ds-color-fg); }
.ds-docdl[data-state="failed"] { color: var(--ds-color-fg-danger); }
@media (prefers-reduced-motion: reduce) { .ds-docdl, .ds-docdl > * { scale: 1; transform: none; transition: opacity var(--ds-duration-micro) var(--ds-easing-standard); } }
`

'use client'
import { Check } from 'lucide-react'
import { PixelButton } from '@/react/components/ui/PixelButton'
import { useDownloadState } from '@/react/hooks/useDocumentDownload'

// The dark button for a document, under an opened document or a result (the console's DownloadButton.vue): red
// pixels come in on hover, and it says Downloaded once it has, since the browser's own bar can sit out of sight. The
// words cross in one cell (.v2-swap): Download leaves up, Downloaded comes up with its check drawing, so the width
// holds. Its state is the document's in useDocumentDownload(), unless `done` says.
export interface DownloadButtonProps {
  id: string
  label?: string
  done?: boolean
  onPress?: () => void
}

export function DownloadButton({ id, label, done, onPress }: DownloadButtonProps) {
  const shared = useDownloadState()
  const isDone = done ?? shared[id] === 'done'
  return (
    <>
      <style href="ds-download-button" precedence="ds">{css}</style>
      <PixelButton data-ds="download-button" done={isDone} onClick={() => onPress?.()}>
        <span className="ds-dlswap" data-on={isDone || undefined}>
          <span className="ds-dlswap-a">{label ?? 'Download'}</span>
          <span className="ds-dlswap-b" aria-hidden="true"><Check size={12} strokeWidth={2} />Downloaded</span>
        </span>
        <span className="sr-only" aria-live="polite">{isDone ? 'downloaded' : ''}</span>
      </PixelButton>
    </>
  )
}

export default DownloadButton

const css = `
.ds-dlswap { display: grid; }
.ds-dlswap > span { display: inline-flex; grid-area: 1 / 1; align-items: center; justify-content: center; gap: var(--ds-space-sm); transition: opacity var(--ds-duration-glide) ease, filter var(--ds-duration-glide) ease, transform var(--ds-duration-settle) var(--ds-easing-out); }
.ds-dlswap-b { opacity: 0; filter: blur(2px); transform: translateY(5px) scale(0.96); }
.ds-dlswap[data-on] .ds-dlswap-a { opacity: 0; filter: blur(2px); transform: translateY(-5px) scale(0.96); }
.ds-dlswap[data-on] .ds-dlswap-b { opacity: 1; filter: none; transform: none; }
.ds-dlswap-b svg path { stroke-dasharray: 24; stroke-dashoffset: 24; transition: stroke-dashoffset var(--ds-duration-micro) ease; }
.ds-dlswap[data-on] .ds-dlswap-b svg path { stroke-dashoffset: 0; transition: stroke-dashoffset var(--ds-duration-enter) var(--ds-easing-out) 40ms; }
@media (prefers-reduced-motion: reduce) {
  .ds-dlswap > span { filter: none; transform: none; transition: opacity var(--ds-duration-micro) ease; }
  .ds-dlswap-b svg path { stroke-dashoffset: 0; transition: none; }
}
`

'use client'
import { useSyncExternalStore } from 'react'

/**
 * A document opens by downloading, never in a panel (the console's useDocumentDownload.ts). The browser's own download
 * bar can sit out of sight, so what was pressed says what happened: each document's state (busy, done, failed) is
 * shared, read by DownloadMark and DownloadButton, and clears 1.8s after. The app hands over the bytes: `get` returns
 * a Blob or text (fetch it from your own API); nothing here calls one.
 */
export type DownloadState = 'busy' | 'done' | 'failed'
let states: Record<string, DownloadState> = {}
const listeners = new Set<() => void>()
const subscribe = (listener: () => void) => {
  listeners.add(listener)
  return () => { listeners.delete(listener) }
}
const get = () => states

function mark(id: string, next?: DownloadState) {
  const all = { ...states }
  if (next) all[id] = next
  else delete all[id]
  states = all
  listeners.forEach(l => l())
}

/** Every document's download state, by id. */
export const useDownloadState = () => useSyncExternalStore(subscribe, get, get)

/** download(id, get, name?) saves what `get` returns as `name` (the id, as text, by default). Works outside components too. */
export async function download(id: string, read: () => Promise<Blob | string> | Blob | string, name?: string) {
  if (states[id] === 'busy') return
  mark(id, 'busy')
  try {
    const body = await read()
    const blob = typeof body === 'string' ? new Blob([body], { type: 'text/plain' }) : body
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = name ?? `${id}.txt`
    a.click()
    URL.revokeObjectURL(url)
    mark(id, 'done')
  }
  catch {
    mark(id, 'failed')
  }
  // ds-latency: the check stays a moment after the download, which has already happened.
  setTimeout(() => mark(id), 1800)
}

export function useDocumentDownload() {
  return download
}

