import { html } from 'lit'
import { html as staticHtml } from 'lit/static-html.js'
import { ifDefined } from 'lit/directives/if-defined.js'
import { Check } from 'lucide'
import { DsElement, define, tag } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import { DownloadStateController, download } from '@/elements/controllers/document-download'
import '@/elements/components/ui/pixel-button'
import styles from 'virtual:tw'

// DownloadButton.vue as <conare-download-button>: the dark button for a document, under an opened document or a result
// (the console's DownloadButton.vue): red pixels come in on hover, and it says Downloaded once it has, since the
// browser's own bar can sit out of sight. The words cross in one cell (.v2-swap): Download leaves up, Downloaded comes
// up with its check drawing, so the width holds. Its state is the document's (controllers/document-download.ts), unless
// `done` says. `download(get, name?)` downloads this document, for a page script with no imports.

/** No attribute: the shared state decides; done or done="true": done; done="false": not done. */
const tristate = { fromAttribute: (v: string | null) => (v === null ? undefined : v !== 'false') }

/**
 * @summary The dark button for a document, saying Downloaded once it has.
 * @fires press - It was pressed (call download(get, name) from here).
 */
export class DownloadButton extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { doc: { attribute: 'doc-id' }, label: {}, done: { converter: tristate } }

	/** The document's id (Vue's `id`; `id` is HTML's own attribute). */
	doc = ''
	/** The word at rest (Download). */
	label?: string
	/** Overrides the shared state; left out, the shared state decides. */
	done?: boolean
	private shared = new DownloadStateController(this)

	/** Downloads this document: saves what `get` returns as `name`. */
	download(get: () => Promise<Blob | string> | Blob | string, name?: string) {
		return download(this.doc, get, name)
	}

	// Vue's fallthrough data-ds="download-button" lands on PixelButton's root, which here sits in the pixel button's own
	// shadow root: it is named there once rendered (Lit leaves an attribute it wrote once alone afterwards).
	protected async firstUpdated(changed: Map<PropertyKey, unknown>) {
		super.firstUpdated(changed)
		const pixel = this.renderRoot.firstElementChild as (HTMLElement & { updateComplete?: Promise<unknown> }) | null
		if (!pixel) return
		await customElements.whenDefined(pixel.localName)
		await pixel.updateComplete
		pixel.shadowRoot?.querySelector('[data-ds="pixel-button"]')?.setAttribute('data-ds', 'download-button')
	}

	render() {
		const isDone = this.done ?? this.shared.state(this.doc) === 'done'
		const pixel = tag('pixel-button')
		return staticHtml`<${pixel} ?done=${isDone} @click=${() => this.emit('press')}><span class="ds-dlswap" data-on=${ifDefined(isDone ? 'true' : undefined)}><span class="ds-dlswap-a">${this.label ?? 'Download'}</span><span class="ds-dlswap-b" aria-hidden="true">${icon(Check, 'check', { size: 12, strokeWidth: 2 })}Downloaded</span></span>${html`<span class="sr-only" aria-live="polite">${isDone ? 'downloaded' : ''}</span>`}</${pixel}>`
	}
}

define('download-button', DownloadButton)

.ds-dlswap { display: grid; }
.ds-dlswap > span { display: inline-flex; grid-area: 1 / 1; align-items: center; justify-content: center; gap: var(--ds-space-sm); transition: opacity var(--ds-duration-glide) ease, filter var(--ds-duration-glide) ease, transform var(--ds-duration-settle) var(--ds-easing-out); }
.ds-dlswap-b { opacity: 0; filter: blur(2px); transform: translateY(5px) scale(0.96); }
.ds-dlswap[data-on] .ds-dlswap-a { opacity: 0; filter: blur(2px); transform: translateY(-5px) scale(0.96); }
.ds-dlswap[data-on] .ds-dlswap-b { opacity: 1; filter: none; transform: none; }
.ds-dlswap-b svg path { stroke-dasharray: 24; stroke-dashoffset: 24; transition: stroke-dashoffset var(--ds-duration-micro) ease; }
.ds-dlswap[data-on] .ds-dlswap-b svg path { stroke-dashoffset: 0; transition: stroke-dashoffset var(--ds-duration-enter) var(--ds-easing-out) 40ms; }
@media (prefers-reduced-motion: reduce) {
  .ds-dlswap > span { filter: none; transform: none; transition: opacity var(--ds-duration-micro) ease; }
  .ds-dlswap-b svg path { stroke-dashoffset: 0; transition: none; }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit'

/**
 * useDocumentDownload as a store and a Lit controller: a document opens by downloading, never in a panel (the
 * console's useDocumentDownload.ts). The browser's own download bar can sit out of sight, so what was pressed says what
 * happened: each document's state (busy, done, failed) is shared, read by <conare-download-mark> and
 * <conare-download-button> (DownloadStateController), and clears 1.8s after. The app hands over the bytes: `get`
 * returns a Blob or text (fetch it from your own API); nothing here calls one.
 *
 * Each element module bundles its own copy of this file, so the states live on one object per page (a global symbol),
 * and every copy reads and writes the same one.
 */
export type DownloadState = 'busy' | 'done' | 'failed'
type Store = { states: Record<string, DownloadState>, listeners: Set<() => void> }
const KEY = Symbol.for('ds.document-download')
const store: Store = ((globalThis as unknown as Record<symbol, Store>)[KEY] ??= { states: {}, listeners: new Set() })

function mark(id: string, next?: DownloadState) {
	const all = { ...store.states }
	if (next) all[id] = next
	else delete all[id]
	store.states = all
	store.listeners.forEach((l) => l())
}

/** Every document's download state, by id. */
export const downloadStates = () => store.states

/** download(id, get, name?) saves what `get` returns as `name` (the id, as text, by default). */
export async function download(id: string, read: () => Promise<Blob | string> | Blob | string, name?: string) {
	if (store.states[id] === 'busy') return
	mark(id, 'busy')
	try {
		const body = await read()
		const blob = typeof body === 'string' ? new Blob([body], { type: 'text/plain' }) : body
		const url = URL.createObjectURL(blob)
		const a = document.createElement('a')
		a.href = url
		a.download = name ?? `${id}.txt`
		a.click()
		URL.revokeObjectURL(url)
		mark(id, 'done')
	} catch {
		mark(id, 'failed')
	}
	// ds-latency: the check stays a moment after the download, which has already happened.
	setTimeout(() => mark(id), 1800)
}

/** Re-renders its element when any document's state changes; `state(id)` reads one. */
export class DownloadStateController implements ReactiveController {
	private off?: () => void
	constructor(private host: ReactiveControllerHost) {
		host.addController(this)
	}
	hostConnected() {
		const listener = () => this.host.requestUpdate()
		store.listeners.add(listener)
		this.off = () => store.listeners.delete(listener)
	}
	hostDisconnected() {
		this.off?.()
	}
	state(id: string): DownloadState | undefined {
		return store.states[id]
	}
}
